namespace ghidra.app.plugin.core.script;



using docking.actions;

class KeyBindingsInfo : Comparable<KeyBindingsInfo> {
	bool hasAction;
	string keystroke;
	string errorMessage;

	KeyBindingsInfo(bool isActionBinding, KeyStroke keyBinding, string errorMessage) : this(isActionBinding, keyBinding)
    {
		this.errorMessage = errorMessage;
	}

	KeyBindingsInfo(bool hasAction, KeyStroke stroke) {
		this.hasAction = hasAction;
		this.keystroke = stroke == null ? "" : KeyBindingUtils.parseKeyStroke(stroke);
	}

	/* @Override */
	public string toString() {
		if (errorMessage != null) {
			return "error";
		}
		return keystroke;
	}

	/* @Override */
	public int compareTo(KeyBindingsInfo o) {
		return keystroke.compareToIgnoreCase(o.keystroke);
	}
}
